// JavaScript port of passguard's analysis (passguard/core.py). Parity with the Python
// version is checked by tests/lab.test.mjs against outputs generated by the real tool.

const GUESSES_PER_SECOND = 1e10;

const COMMON_PASSWORDS = `
password 123456 123456789 12345678 12345 1234567 1234567890 qwerty qwerty123
abc123 password1 password123 iloveyou admin welcome login letmein monkey
dragon football baseball master sunshine princess shadow superman trustno1
passw0rd 111111 000000 123123 654321 666666 121212 qazwsx qwertyuiop
1q2w3e4r 1qaz2wsx zaq12wsx changeme secret hello freedom whatever starwars
batman flower hunter ranger
`.split(/\s+/).filter(Boolean);
const COMMON = new Set(COMMON_PASSWORDS);

const ROWS = ['abcdefghijklmnopqrstuvwxyz', '0123456789', 'qwertyuiop', 'asdfghjkl', 'zxcvbnm'];
const LEET = { 0: 'o', 1: 'l', 3: 'e', 4: 'a', 5: 's', 7: 't', '@': 'a', $: 's', '!': 'i' };
const RATINGS = [[28, 'Very weak'], [36, 'Weak'], [60, 'Fair'], [80, 'Strong']];
const PUNCT = '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~';

const chars = (s) => Array.from(s); // by code point, like Python's str

/** Python's round(): halves go to the even number. */
function pyRound(x, digits = 0) {
  const f = 10 ** digits;
  const y = x * f;
  const r = Math.round(y);
  const rounded = Math.abs(y % 1) === 0.5 && r % 2 !== 0 ? r - 1 : r;
  return rounded / f;
}

export function charsetSize(password) {
  let pool = 0;
  const cs = chars(password);
  if (cs.some((c) => /^[a-z]$/.test(c))) pool += 26;
  if (cs.some((c) => /^[A-Z]$/.test(c))) pool += 26;
  if (cs.some((c) => /^[0-9]$/.test(c))) pool += 10;
  if (cs.some((c) => PUNCT.includes(c))) pool += PUNCT.length;
  if (cs.some((c) => c.codePointAt(0) > 127 || /\s/.test(c))) pool += 32;
  return pool;
}

export function findSequences(password) {
  const lowered = chars(password.toLowerCase());
  const original = chars(password);
  const found = [];
  let i = 0;
  while (i < lowered.length - 2) {
    let best = 0;
    for (const row of ROWS) {
      for (const seq of [row, row.split('').reverse().join('')]) {
        let j = i;
        while (j + 1 < lowered.length) {
          const pos = seq.indexOf(lowered[j]);
          if (pos === -1 || seq[pos + 1] !== lowered[j + 1]) break;
          j += 1;
        }
        best = Math.max(best, j - i + 1);
      }
    }
    if (best >= 3) { found.push(original.slice(i, i + best).join('')); i += best; } else i += 1;
  }
  return found;
}

export function humanizeSeconds(seconds) {
  if (seconds < 1) return 'instantly';
  const units = [[60, 'second', 1], [3600, 'minute', 60], [86400, 'hour', 3600], [86400 * 365, 'day', 86400]];
  for (const [limit, name, size] of units) {
    if (seconds < limit) {
      const value = Math.floor(seconds / size);
      return `${value} ${name}${value !== 1 ? 's' : ''}`;
    }
  }
  const years = seconds / (86400 * 365);
  if (years < 1000) { const v = Math.floor(years); return `${v} year${v !== 1 ? 's' : ''}`; }
  if (years < 1e6) return `~${(years / 1e3).toFixed(0)} thousand years`;
  if (years < 1e9) return `~${(years / 1e6).toFixed(0)} million years`;
  return 'billions of years or more';
}

const leet = (s) => chars(s).map((c) => LEET[c] ?? c).join('');

export function analyze(password) {
  if (!password) {
    return { length: 0, entropy_bits: 0, score: 0, rating: 'Very weak', crack_time: 'instantly',
      issues: ['The password is empty.'], suggestions: ['Use a long passphrase or a generated password.'] };
  }
  const issues = [];
  const pool = charsetSize(password);
  const collapsed = password.replace(/(.)\1{2,}/gu, '$1');
  let effective = chars(collapsed).length;
  if (chars(collapsed).length < chars(password).length) issues.push('Contains repeated characters.');

  for (const run of findSequences(collapsed)) {
    effective -= chars(run).length - 1;
    issues.push(`Contains a predictable sequence (${chars(run).length} characters).`);
  }
  const years = password.match(/(?:19|20)\d{2}/g) || [];
  if (years.length) { effective -= 2 * years.length; issues.push('Contains a year, which is easy to guess.'); }

  const lowered = password.toLowerCase();
  const stripped = lowered.replace(/[^\p{L}]+$/u, '');
  const candidates = new Set([lowered, leet(lowered), stripped, leet(stripped)]);
  const isCommon = [...candidates].some((c) => COMMON.has(c));
  if (isCommon) issues.push('This is a very common password.');
  else {
    for (const word of COMMON_PASSWORDS) {
      if (word.length >= 5 && [...candidates].some((c) => c.includes(word))) {
        effective -= word.length;
        issues.push('Contains a very common password or word.');
        break;
      }
    }
  }
  if (chars(password).length < 8) issues.push('Shorter than 8 characters.');

  effective = Math.max(effective, 0);
  let entropy = pool > 1 ? effective * Math.log2(pool) : 0;
  if (isCommon) entropy = Math.min(entropy, 12);
  entropy = pyRound(entropy, 1);

  let rating = 'Very strong';
  for (const [limit, label] of RATINGS) if (entropy < limit) { rating = label; break; }
  const score = Math.min(100, pyRound((entropy / 80) * 100));
  const seconds = 2 ** (Math.min(entropy, 1000) - 1) / GUESSES_PER_SECOND;

  const suggestions = [];
  if (['Very weak', 'Weak', 'Fair'].includes(rating)) {
    if (chars(password).length < 12) suggestions.push('Use at least 12 characters; 16 or more is better.');
    suggestions.push('Try a passphrase of 4+ unrelated random words.');
    suggestions.push('Use a password manager and a unique password for every site.');
  }
  return { length: chars(password).length, entropy_bits: entropy, score, rating, crack_time: humanizeSeconds(seconds), issues, suggestions };
}

/** SHA-1 as uppercase hex, plus the 5-character prefix a k-anonymity breach lookup would send. */
export async function sha1Parts(password) {
  const digest = await crypto.subtle.digest('SHA-1', new TextEncoder().encode(password));
  const hex = Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('').toUpperCase();
  return { hex, prefix: hex.slice(0, 5), suffix: hex.slice(5) };
}
